class ExprError(Exception):
    def __init__(self, kind: str, pos: int):
        self.kind = kind
        self.pos = pos
        super().__init__(f"{kind} error at position {pos}")


def _is_digit(c):
    return "0" <= c <= "9"


def _is_ident_start(c):
    return "A" <= c <= "Z" or "a" <= c <= "z" or c == "_"


def _is_ident_part(c):
    return _is_ident_start(c) or _is_digit(c)


def _decimal_integer(text):
    # Avoid Python's configurable limit on decimal string-to-int conversions.
    value = 0
    for start in range(0, len(text), 9):
        chunk = text[start:start + 9]
        value = value * (10 ** len(chunk)) + int(chunk)
    return value


class _Lexer:
    """Lazy tokenization preserves the first left-to-right syntax error."""

    _TWO_CHAR = frozenset(("||", "&&", "==", "!=", "<=", ">=", "**"))
    _ONE_CHAR = frozenset("!<>+-*/%?:(),")

    def __init__(self, src):
        self.src = src
        self.index = 0
        self.cached = None

    def peek(self):
        if self.cached is None:
            self.cached = self._scan()
        return self.cached

    def take(self):
        token = self.peek()
        self.cached = None
        return token

    def expect(self, kind):
        token = self.peek()
        if token[0] != kind:
            raise ExprError("syntax", token[1])
        return self.take()

    def _scan(self):
        src = self.src
        n = len(src)
        i = self.index

        while i < n and src[i] in " \t\n":
            i += 1

        if i == n:
            self.index = i
            return ("EOF", n, None)

        start = i
        c = src[i]

        if _is_digit(c):
            i += 1
            while i < n and _is_digit(src[i]):
                i += 1
            if c == "0" and i - start > 1:
                raise ExprError("syntax", start)
            self.index = i
            return ("INT", start, _decimal_integer(src[start:i]))

        if _is_ident_start(c):
            i += 1
            while i < n and _is_ident_part(src[i]):
                i += 1
            name = src[start:i]
            self.index = i
            if name == "true":
                return ("BOOL", start, True)
            if name == "false":
                return ("BOOL", start, False)
            return ("ID", start, name)

        pair = src[i:i + 2]
        if pair in self._TWO_CHAR:
            self.index = i + 2
            return (pair, start, None)

        if c in self._ONE_CHAR:
            self.index = i + 1
            return (c, start, None)

        raise ExprError("syntax", start)


# Operator -> (left binding power, right binding power, nonassociation bit).
# Power's right operand admits unary operators, while its left binding
# power is greater than unary's.
_INFIX = {
    "||": (20, 21, 0),
    "&&": (30, 31, 0),
    "==": (40, 41, 1),
    "!=": (40, 41, 1),
    "<":  (50, 51, 2),
    "<=": (50, 51, 2),
    ">":  (50, 51, 2),
    ">=": (50, 51, 2),
    "+":  (60, 61, 0),
    "-":  (60, 61, 0),
    "*":  (70, 71, 0),
    "/":  (70, 71, 0),
    "%":  (70, 71, 0),
    "**": (90, 80, 0),
}


def _parse(src):
    """
    Iterative Pratt parser.

    Tasks replace recursive parser calls, so long operator chains and deeply
    nested expressions do not consume the Python call stack.
    """
    lexer = _Lexer(src)
    tasks = [("expr", 0)]
    values = []

    while tasks:
        task = tasks.pop()
        action = task[0]

        if action == "expr":
            minimum = task[1]
            kind, pos, value = lexer.peek()

            if kind == "INT" or kind == "BOOL":
                lexer.take()
                values.append(("literal", pos, value))
                tasks.append(("loop", minimum, 0))

            elif kind == "ID":
                lexer.take()
                tasks.append(("loop", minimum, 0))

                if lexer.peek()[0] == "(":
                    lexer.take()
                    if lexer.peek()[0] == ")":
                        lexer.take()
                        values.append(("call", pos, value, ()))
                    else:
                        args = []
                        tasks.append(("call_arg", pos, value, args))
                        tasks.append(("expr", 0))
                else:
                    values.append(("variable", pos, value))

            elif kind == "(":
                lexer.take()
                tasks.append(("loop", minimum, 0))
                tasks.append(("close_paren",))
                tasks.append(("expr", 0))

            elif kind == "-" or kind == "!":
                lexer.take()
                tasks.append(("loop", minimum, 0))
                tasks.append(("make_unary", pos, kind))
                tasks.append(("expr", 80))

            else:
                raise ExprError("syntax", pos)

        elif action == "loop":
            minimum, used_nonassoc = task[1:]
            kind, pos, _ = lexer.peek()

            if kind == "?" and minimum <= 10:
                lexer.take()
                tasks.append(("loop", minimum, used_nonassoc))
                tasks.append(("ternary_middle", pos))
                tasks.append(("expr", 0))
                continue

            info = _INFIX.get(kind)
            if info is None or info[0] < minimum:
                continue

            _, right_minimum, nonassoc_bit = info
            if nonassoc_bit & used_nonassoc:
                raise ExprError("syntax", pos)

            lexer.take()
            tasks.append((
                "loop", minimum, used_nonassoc | nonassoc_bit
            ))
            tasks.append(("make_binary", pos, kind))
            tasks.append(("expr", right_minimum))

        elif action == "close_paren":
            lexer.expect(")")

        elif action == "make_unary":
            operand = values.pop()
            values.append(("unary", task[1], task[2], operand))

        elif action == "make_binary":
            right = values.pop()
            left = values.pop()
            values.append(("binary", task[1], task[2], left, right))

        elif action == "ternary_middle":
            lexer.expect(":")
            tasks.append(("make_ternary", task[1]))
            tasks.append(("expr", 0))

        elif action == "make_ternary":
            otherwise = values.pop()
            selected = values.pop()
            condition = values.pop()
            values.append((
                "ternary", task[1], condition, selected, otherwise
            ))

        elif action == "call_arg":
            pos, name, args = task[1:]
            args.append(values.pop())
            kind, delimiter_pos, _ = lexer.peek()

            if kind == ",":
                lexer.take()
                tasks.append(("call_arg", pos, name, args))
                tasks.append(("expr", 0))
            elif kind == ")":
                lexer.take()
                values.append(("call", pos, name, tuple(args)))
            else:
                raise ExprError("syntax", delimiter_pos)

        else:
            raise AssertionError("Unknown parser task")

    lexer.expect("EOF")
    assert len(values) == 1
    return values[0]


def _require_bool(value, pos):
    if type(value) is not bool:
        raise ExprError("type", pos)


def _apply_binary(op, pos, left, right):
    if op == "==" or op == "!=":
        if type(left) not in (int, bool) or type(left) is not type(right):
            raise ExprError("type", pos)
        return left == right if op == "==" else left != right

    if type(left) is not int or type(right) is not int:
        raise ExprError("type", pos)

    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right

    if op == "/" or op == "%":
        if right == 0:
            raise ExprError("zero-division", pos)
        quotient = abs(left) // abs(right)
        if (left < 0) != (right < 0):
            quotient = -quotient
        if op == "/":
            return quotient
        return left - quotient * right

    if op == "**":
        if not 0 <= right <= 1000:
            raise ExprError("domain", pos)
        return left ** right

    if op == "<":
        return left < right
    if op == "<=":
        return left <= right
    if op == ">":
        return left > right
    if op == ">=":
        return left >= right

    raise AssertionError("Unknown binary operator")


def _evaluate_tree(root, env):
    """Evaluate with an explicit stack, preserving all specified ordering."""
    tasks = [("eval", root)]
    values = []

    while tasks:
        task = tasks.pop()
        action = task[0]

        if action == "eval":
            node = task[1]
            kind, pos = node[:2]

            if kind == "literal":
                values.append(node[2])

            elif kind == "variable":
                name = node[2]
                if name not in env:
                    raise ExprError("name", pos)
                values.append(env[name])

            elif kind == "unary":
                op, operand = node[2:]
                tasks.append(("unary", op, pos))
                tasks.append(("eval", operand))

            elif kind == "binary":
                op, left, right = node[2:]
                if op == "&&" or op == "||":
                    tasks.append(("logical_left", op, pos, right))
                    tasks.append(("eval", left))
                else:
                    tasks.append(("binary", op, pos))
                    tasks.append(("eval", right))
                    tasks.append(("eval", left))

            elif kind == "ternary":
                condition, selected, otherwise = node[2:]
                tasks.append(("select", pos, selected, otherwise))
                tasks.append(("eval", condition))

            elif kind == "call":
                name, args = node[2:]
                count = len(args)

                # Name and arity checks precede every argument evaluation.
                if name not in ("min", "max", "abs"):
                    raise ExprError("name", pos)
                if (name == "abs" and count != 1) or (
                    name != "abs" and count == 0
                ):
                    raise ExprError("arity", pos)

                tasks.append(("call", name, pos, count))
                for arg in reversed(args):
                    tasks.append(("eval", arg))

            else:
                raise AssertionError("Unknown AST node")

        elif action == "unary":
            op, pos = task[1:]
            operand = values.pop()
            if op == "!":
                _require_bool(operand, pos)
                values.append(not operand)
            else:
                if type(operand) is not int:
                    raise ExprError("type", pos)
                values.append(-operand)

        elif action == "binary":
            op, pos = task[1:]
            right = values.pop()
            left = values.pop()
            values.append(_apply_binary(op, pos, left, right))

        elif action == "logical_left":
            op, pos, right = task[1:]
            left = values.pop()
            _require_bool(left, pos)

            if (op == "&&" and not left) or (op == "||" and left):
                values.append(left)
            else:
                tasks.append(("check_bool", pos))
                tasks.append(("eval", right))

        elif action == "check_bool":
            _require_bool(values[-1], task[1])

        elif action == "select":
            pos, selected, otherwise = task[1:]
            condition = values.pop()
            _require_bool(condition, pos)
            tasks.append(("eval", selected if condition else otherwise))

        elif action == "call":
            name, pos, count = task[1:]
            args = values[-count:]
            del values[-count:]

            # All arguments have already been evaluated left to right.
            if any(type(arg) is not int for arg in args):
                raise ExprError("type", pos)

            if name == "abs":
                values.append(abs(args[0]))
            elif name == "min":
                values.append(min(args))
            else:
                values.append(max(args))

        else:
            raise AssertionError("Unknown evaluation task")

    assert len(values) == 1
    return values[0]


def evaluate(src: str, env: dict):
    """Return a Python int or bool, or raise ExprError(kind, pos)."""
    # Parse the entire input before performing any semantic checks.
    root = _parse(src)
    return _evaluate_tree(root, env)
